      const l = e.acceleration || {}, g = e.accelerationIncludingGravity || {}, r = v => v == null ? null : +v;
      this.xyz.lx.push(r(l.x)); this.xyz.ly.push(r(l.y)); this.xyz.lz.push(r(l.z));
