/* The trimmed clip with the path drawn as it goes, recorded in real time for sharing. */
async function bpRender(bg, video, from, to, X, Y, repIdx) {
  const mime = clipMime();
  if (!mime) return toast('This browser can\'t make a video file');
  const k = Math.min(1, 720 / video.videoHeight);
  const c = document.createElement('canvas'); c.width = Math.round(video.videoWidth * k / 2) * 2; c.height = Math.round(video.videoHeight * k / 2) * 2;
  const x = c.getContext('2d');
  const cols = SERIES_COLORS.map(s => window.getComputedStyle(document.documentElement).getPropertyValue(s.slice(4, -1)).trim() || '#ff6b35');
  const btn = $('#bpRender', bg); if (btn) { btn.disabled = true; btn.textContent = 'Making it…'; }
  Awake.hold('bprender');
  const rec = clipRecorder(c, { bps: 4e6 });
  let raf = 0;
  const frame = () => {
    x.drawImage(video, 0, 0, c.width, c.height);
    const upto = Math.floor((video.currentTime - from) * BP.hz);
    x.lineWidth = 4; x.lineJoin = 'round';
    repIdx.forEach((ix, r) => {
      const pts = ix.filter(i => i <= upto);
      if (pts.length < 2) return;
      x.strokeStyle = cols[r % cols.length];
      x.beginPath(); pts.forEach((i, j) => j ? x.lineTo(X[i] * c.width, Y[i] * c.height) : x.moveTo(X[i] * c.width, Y[i] * c.height)); x.stroke();
    });
    raf = requestAnimationFrame(frame);
  };
  try {
    await bpSeek(video, from);
    frame(); rec.start();
    await video.play();
    await new Promise(res => { const iv = setInterval(() => { if (video.currentTime >= to || video.ended || video.paused) { clearInterval(iv); res(); } }, 50); });
    video.pause();
    const blob = await rec.stop();
    cancelAnimationFrame(raf);
    const name = `ironlog-barpath-${today()}.${mime.includes('mp4') ? 'mp4' : 'webm'}`;
    const file = new File([blob], name, { type: blob.type });
    if (navigator.canShare && navigator.canShare({ files: [file] })) navigator.share({ files: [file], title: 'Bar path' }).catch(() => {});
    else { const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = name; document.body.appendChild(a); a.click(); a.remove(); }
    toast('Bar path video made', 'green');
  } catch (e) { toast(`Couldn't make the video — ${e.message || e}`); }
  finally { cancelAnimationFrame(raf); Awake.release('bprender'); if (btn) { btn.disabled = false; btn.textContent = 'Save with bar path'; } }
}

/* ============================================================
   VBT PROFILE — roadmap D1, r&d/specs/vbt-overhaul-spec.md
   Profile mode: each measured warm-up is a (load, best-rep speed) point; a
   straight line through them meets the lift's minimum velocity threshold at
   the day's e1RM, shown as a range because a phone is not a transducer.
   Pocket readings are shown but never fitted.
   ============================================================ */
function lvLine(pts) {
  const n = pts.length, mx = pts.reduce((a, p) => a + p.kg, 0) / n, my = pts.reduce((a, p) => a + p.v, 0) / n;
  let sxy = 0, sxx = 0;
  pts.forEach(p => { sxy += (p.kg - mx) * (p.v - my); sxx += (p.kg - mx) ** 2; });
  const b = sxx ? sxy / sxx : 0, a = my - b * mx;
  const rse = n > 2 ? Math.sqrt(pts.reduce((s, p) => s + (p.v - (a + b * p.kg)) ** 2, 0) / (n - 2)) : 0;
  return { a, b, rse };
}
/* Outliers: heavier can't be faster. A point more than LV_SLACK m/s faster
   than a lighter one breaks that — usually a first warm-up rep that wasn't
   moved with intent, or the next one ramped up. Of the points in such a clash,
   the one whose removal leaves the tightest line is left out; repeat while a
   clash remains and more than three points are left. Points that only bend
   the line (the heaviest warm-up slowing down a lot) are real and stay. */
const LV_SLACK = 0.05;
