  if (all.length < 3) return null;
  const { keep: pts, out } = lvOutliers(all);
  const kgs = pts.map(p => p.kg), maxKg = Math.max(...kgs), minKg = Math.min(...kgs);
  if ((maxKg - minKg) / maxKg < 0.15) return null;   // too narrow a ramp to draw a line through
