    home: { k2w: { L: mob('k2w', 'L'), R: mob('k2w', 'R') }, scratch: { L: mob('scratch', 'L'), R: mob('scratch', 'R') },
      ohs: { flat: mob('ohs', null), heels: mob('ohs_heels', null) }, bal: { L: null, R: null }, balTimer: false },
    power: { mode: lastPower ? lastPower.mode : (vbtAvailable() ? 'speed' : 'jump'), cm: null, mps: null, kg: null },
