      const j = rest.findIndex(s => s.p === pp);
      if (j < 0 || keep.some(s => s.p === pp)) return;
      let k = -1;
      keep.forEach((s, x) => { if ((s.role === 'accessory' || s.role === 'finisher') && !promote.includes(s.p)) k = x; });
      if (k < 0) return;
