  if (D.week.missed >= 2) focus.push([4, 'Consistency first: get every planned session in, even short ones.']);
  if (D.prs.length) L.push(`PRs: ${esc(D.prs.map(p => `${p.name} ${prText(p)}`).join(', '))}.`);
  const moving = D.lifts.filter(l => l.now && l.then && l.now > l.then * 1.01), stalled = D.lifts.filter(l => l.stall);
  if (D.lifts.length) L.push(D.lifts.map(coLiftLine).join('<br>'));
  if (stalled.length) focus.push([3, `${stalled[0].name} has stalled — ask me why.`]);
  const low = Object.entries(D.muscles).filter(([, v]) => v < CO_LOW_SETS).map(([k]) => MUSCLES[k] || k);
  if (low.length && D.week.done) { L.push(`Low volume: ${esc(low.slice(0, 5).join(', '))}.`); focus.push([1, `Give ${low[0].toLowerCase()} a few more sets.`]); }
  const c = D.ci, p = D.ciPrev;
  const now = [c.sleep ? `sleep ${nice(c.sleep)} h` : '', c.energy ? `energy ${nice(c.energy)}/5` : '', c.soreness ? `soreness ${nice(c.soreness)}/5` : ''].filter(Boolean);
  const was = [p.sleep ? `${nice(p.sleep)} h` : '', p.energy ? `${nice(p.energy)}/5` : ''].filter(Boolean);
  if (now.length) L.push(`Check-ins: ${now.join(', ')}${was.length ? ` (last week ${was.join(', ')})` : ''}.`);
  if (c.sleep && c.sleep < 6.5) focus.push([3, 'Sleep is the cheapest win this week — aim for 7–9 h.']);
  if (c.weight && D.bwThen) L.push(`Bodyweight ${coKg(c.weight)} (${c.weight >= D.bwThen ? '+' : '−'}${coKg(Math.abs(c.weight - D.bwThen))} in a month).`);
  if (D.event) L.push(`${esc(D.event.name || 'Event')} in ${daysBetween(D.t, D.event.date)} days${D.block ? ` — ${esc(D.block.kind.label.toLowerCase())} block, week ${D.block.week}` : ''}.`);
  const dl = coDeloadScore(D);
  if (dl.score >= 3) focus.push([5, 'Take a lighter week: half the sets, RIR 3–4.']);
