  if (wd && (wd.length !== days.length || wd.some(d => !wdKeys.includes(d)))) { warn.push('The weekdays didn\'t match the days — placed them for you.'); wd = null; }
  if (!wd) { wd = PLAN_DEFAULT_DAYS[days.length]; if (!Array.isArray(obj.weekdays)) warn.push(`No weekdays given — put on ${wd.map(d => COACH_WD.find(w => w[0] === d)[1]).join(', ')}.`); }
