      const o = { w: +s.kg > 0 ? +s.kg : null, r, type: { warmup: 'warmup', top: 'top', topset: 'top', backoff: 'backoff', amrap: 'amrap', drop: 'drop', dropset: 'drop' }[type] || 'working' };
      if (o.w) anyKg = true;
      if (s.rir != null && s.rir !== '' && !isNaN(+s.rir)) o.t = clamp(Math.round(+s.rir), 0, 10);
      if (+s.seconds > 0) o.sec = Math.round(+s.seconds);
